import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { ArrowRight, BookOpen, Target, TrendingUp, Code2 } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import { getUserResults } from "../../services/resumeService";

const BG = "data:image/png;base64,";

const ParticleField = () => {
  const particles = Array.from({ length: 30 }, (_, i) => ({
    id: i,
    x: 50 + Math.random() * 50,
    y: Math.random() * 100,
    size: Math.random() * 2 + 0.8,
    delay: Math.random() * 5,
    duration: Math.random() * 8 + 5,
  }));
  return (
    <div className="absolute inset-0 overflow-hidden pointer-events-none z-10">
      {particles.map((p) => (
        <motion.div
          key={p.id}
          className="absolute rounded-full bg-amber-400"
          style={{ left: `${p.x}%`, top: `${p.y}%`, width: p.size, height: p.size }}
          animate={{ y: [0, -30, 0], opacity: [0.08, 0.3, 0.08] }}
          transition={{ duration: p.duration, delay: p.delay, repeat: Infinity, ease: "easeInOut" }}
        />
      ))}
    </div>
  );
};

const HeroSection = () => {
  const [hovered, setHovered] = useState(false);
  const [roadmapCompany, setRoadmapCompany] = useState("");
  const navigate = useNavigate();
  const { user } = useAuth();

  useEffect(() => {
    const loadRoadmapCompany = async () => {
      if (!user?.uid) { setRoadmapCompany(""); return; }
      const data = await getUserResults(user.uid);
      setRoadmapCompany(data?.companies?.[0]?.name || "");
    };
    loadRoadmapCompany();
  }, [user?.uid]);

  const handleStartPreparing = () => navigate(user ? "/dashboard" : "/login");
  const handleExploreRoadmap = () => {
    if (!user) return navigate("/login");
    navigate(roadmapCompany ? `/plan/${roadmapCompany}` : "/dashboard");
  };

  return (
    <section className="relative h-screen min-h-[650px] flex items-center overflow-hidden bg-[#070605]">

      {/* ── Background image — positioned so staircase is on the right ── */}
      <div
        className="absolute inset-0 z-0 bg-cover bg-no-repeat"
        style={{ backgroundImage: `url(${BG})`, backgroundPosition: "65% center" }}
      />



      {/* ── Top & bottom fades ── */}
      <div
        className="absolute inset-0 z-10 pointer-events-none"
        style={{
          background: "linear-gradient(to bottom, rgba(7,6,5,0.55) 0%, transparent 15%, transparent 80%, rgba(7,6,5,0.85) 100%)"
        }}
      />

      {/* ── Particles (right half only) ── */}
      <ParticleField />

      {/* ── Content — left aligned, navbar-aware ── */}
      <div className="relative z-20 w-full max-w-7xl mx-auto px-6 lg:px-16 pt-20">
        <div className="flex flex-col items-start max-w-xl">

          {/* Badge */}
          <motion.div
            initial={{ opacity: 0, y: -12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="flex items-center gap-2 px-4 py-2 rounded-full bg-amber-500/10 border border-amber-500/20 mb-8"
          >
            <span className="w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-amber-400">
              Precision Drive 2026
            </span>
          </motion.div>

          {/* Headline */}
          <motion.h1
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.1, ease: [0.22, 1, 0.36, 1] }}
            className="font-black leading-[0.88] tracking-[-0.03em] mb-6"
            style={{ fontFamily: "'Bebas Neue', cursive", fontSize: "clamp(64px, 8vw, 108px)" }}
          >
            <style>{`@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:wght@300;400;700;900&display=swap');`}</style>
            <span
              className="block italic"
              style={{ color: "transparent", WebkitTextStroke: "1.5px rgba(245,158,11,0.55)" }}
            >
              Target.
            </span>
            <span className="block text-white">Train.</span>
            <span
              className="block text-amber-400"
              style={{ textShadow: "0 0 40px rgba(245,158,11,0.45)" }}
            >
              Triumph.
            </span>
          </motion.h1>

          {/* Body */}
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.38, duration: 0.6 }}
            className="text-[14px] leading-relaxed mb-10"
            style={{ color: "rgba(255,255,255,0.38)", fontFamily: "DM Sans, sans-serif", fontWeight: 300, maxWidth: 380 }}
          >
            The definitive AI ecosystem for placement mastery. Crack DSA, ace mock interviews,
            and land your dream offer — all in one precision-built platform.
          </motion.p>

          {/* CTA Buttons */}
          <motion.div
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.52 }}
            className="flex flex-wrap items-center gap-4 mb-12"
          >
            <motion.button
              onHoverStart={() => setHovered(true)}
              onHoverEnd={() => setHovered(false)}
              whileHover={{ scale: 1.03, boxShadow: "0 0 28px rgba(245,158,11,0.35)" }}
              whileTap={{ scale: 0.97 }}
              onClick={handleStartPreparing}
              className="relative group flex items-center gap-3 px-8 py-[15px] rounded-xl text-black font-black uppercase tracking-widest text-[11px] overflow-hidden border-0"
              style={{ background: "linear-gradient(135deg, #f59e0b, #d97706)", fontFamily: "DM Sans, sans-serif" }}
            >
              Start Preparing
              <motion.span animate={{ x: hovered ? 4 : 0 }} transition={{ type: "spring", stiffness: 300 }}>
                <ArrowRight size={15} />
              </motion.span>
            </motion.button>

            <motion.button
              whileHover={{ scale: 1.02, borderColor: "rgba(245,158,11,0.3)", color: "rgba(255,255,255,0.85)" }}
              whileTap={{ scale: 0.97 }}
              onClick={handleExploreRoadmap}
              className="flex items-center gap-2 px-8 py-[15px] rounded-xl font-bold uppercase tracking-widest text-[11px] transition-all"
              style={{
                border: "1px solid rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.45)",
                background: "transparent",
                fontFamily: "DM Sans, sans-serif",
              }}
            >
              <BookOpen size={14} />
              Explore Roadmap
            </motion.button>
          </motion.div>

          {/* Stats row */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.75 }}
            className="flex items-center gap-8"
          >
            {[
              { icon: Target,    value: "24+",  label: "Companies" },
              { icon: Code2,     value: "500+", label: "Problems"  },
              { icon: TrendingUp,value: "86%",  label: "Readiness" },
            ].map(({ icon: Icon, value, label }) => (
              <div key={label} className="flex items-center gap-3">
                <div
                  className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
                  style={{ background: "rgba(245,158,11,0.08)", border: "1px solid rgba(245,158,11,0.15)" }}
                >
                  <Icon size={13} color="#f59e0b" />
                </div>
                <div>
                  <p style={{ fontFamily: "Bebas Neue, cursive", fontSize: 22, color: "#fff", lineHeight: 1, margin: 0 }}>
                    {value}
                  </p>
                  <p style={{ fontFamily: "DM Sans, sans-serif", fontSize: 8, color: "rgba(255,255,255,0.25)", letterSpacing: "0.25em", textTransform: "uppercase", margin: "3px 0 0" }}>
                    {label}
                  </p>
                </div>
              </div>
            ))}
          </motion.div>

        </div>
      </div>

      {/* Bottom fade */}
      <div className="absolute bottom-0 inset-x-0 h-28 pointer-events-none z-20"
        style={{ background: "linear-gradient(to top, rgba(7,6,5,0.9), transparent)" }}
      />
    </section>
  );
};

export default HeroSection;